public static Tuple<String, String> getProjectIdAndRegionFromResourceName(String resourceName, String pattern) {
    Matcher match = Pattern.compile(pattern).matcher(resourceName);
    if (!match.matches()) {
        throw new IllegalArgumentException(String.format("resource name %s is not valid.", resourceName));
    }
    return new Tuple<>(match.group(1), match.group(2));
}
